using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Abstractions.Persistence.Specifications;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;using DomainRateType=OAS.Domain.Accounting.Enums.ExchangeRateType;
namespace OAS.Application.Accounting.ExchangeRates.Commands.UpdateExchangeRate;
public sealed class UpdateExchangeRateCommandHandler(IRepository<ExchangeRate,Guid> repository,IReadRepository<AccountingSettings,Guid> settings):IRequestHandler<UpdateExchangeRateCommand>
{
 public async Task Handle(UpdateExchangeRateCommand r,CancellationToken ct){var e=await repository.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(ExchangeRate),r.Id);byte[] rv;try{rv=Convert.FromBase64String(r.Request.RowVersion);}catch(FormatException ex){throw new ConcurrencyException("Exchange rate row version is invalid.",ex);}if(!e.RowVersion.SequenceEqual(rv))throw new ConcurrencyException("Exchange rate was modified by another user.");var type=(DomainRateType)(byte)r.Request.RateType;var st=await settings.GetByIdAsync(AccountingSettings.SingletonId,ct);if(st?.BaseCurrencyId==e.CurrencyId&&r.Request.Rate!=1m)throw new ConflictException("base_currency_rate_must_be_one","Base currency exchange rate must equal 1.");if(await repository.CountAsync(new Specification<ExchangeRate>().Where(x=>x.Id!=e.Id&&x.CurrencyId==e.CurrencyId&&x.RateDate==r.Request.RateDate&&x.RateType==type),ct)>0)throw new ConflictException("exchange_rate_duplicate","An exchange rate already exists for the same currency, date and rate type.");e.Update(r.Request.RateDate,r.Request.Rate,type,r.Request.IsActive);repository.Update(e);}
}
